result:
.el-radio-group{
  height: 300px;
  overflow: auto;
  margin-top: 5px;
}
.shang{
  display: flex;
  justify-content: space-between;
  align-items: center;

  .el-form-item {
    margin-bottom: 5px;
  }
  .shang-l{
    flex: 1;
  }
  .el-icon-sort{
    transform: rotate(90deg);
    font-size: 21px;
    font-weight: bold;
  }
  .shang-r{
    flex: 1;
  }
  .middle{
    border: 1px solid rgb(217,217,217);
    border-radius: 5px;
    padding: 10px 15px;
    position: relative;

    .middle_t{
      border-bottom: 1px solid #d9d9d9;
      padding-bottom: 8px;
      margin-bottom: 5px;
      font-size: 15px;
    }

    .el-radio{
      display: block;
      margin-top: 9px;
    }

  }
}

.zhong{
  border: 1px solid rgb(217,217,217);
  border-radius: 5px;
  padding: 10px 15px;
  margin-top: 20px;
  height: 200px;
  overflow: auto;
  .zhong-l{
    display: flex;
  }
  .zhong-r{
    margin-right: 20px;
  }
  .zhong-c{
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin: 5px 0;

    span{
      color: #409EFF;
      margin: 0 15px;
    }
  }
}
